import os,hashlib,re
def solve(root):
 d={}
 for dp,ds,fs in os.walk(root):
  ds[:]=[x for x in ds if not os.path.islink(os.path.join(dp,x))]
  for f in fs:
   p=os.path.join(dp,f)
   if not f.lower().endswith('.txt') or os.path.islink(p):continue
   with open(p,encoding='utf8') as h:s=re.sub(r'\s+',' ',h.read().casefold()).strip()
   k=hashlib.sha256(s.encode()).hexdigest();d.setdefault(k,[]).append(p)
 return [{'fingerprint':k,'files':sorted(v)} for k,v in sorted(d.items()) if len(v)>1]

